return $input.all().map(item => {
  const output = item.json.output || {};
  const suspeito = /confirmad[oa]|marcad[oa]|reservad[oa]|agendad[oa]/i;

  if (output.intencao === 'duvida' && suspeito.test(output.confirmacao_texto || '')) {
    if (output.data_hora_inicio) {
      return { json: { ...item.json, output: { ...output, intencao: 'agendar' } } };
    }

    return {
      json: {
        ...item.json,
        output: {
          ...output,
          confirmacao_texto: 'Pode me confirmar o dia e o horário exatos que você gostaria? Assim eu já verifico a disponibilidade certinho.'
        }
      }
    };
  }

  return item;
});

return $input.all().map(item => {
  const output = item.json.output || {};
  const inicio = DateTime.fromISO(output.data_hora_inicio, { zone: 'America/Sao_Paulo' });
  const fim = DateTime.fromISO(output.data_hora_fim, { zone: 'America/Sao_Paulo' });

  const abertura = 9 * 60;
  const fechamento = 18 * 60;
  const minutosInicio = inicio.hour * 60 + inicio.minute;
  const minutosFim = fim.hour * 60 + fim.minute;
  const domingo = inicio.weekday === 7;

  const dentroDoExpediente =
    inicio.isValid &&
    fim.isValid &&
    !domingo &&
    minutosInicio >= abertura &&
    minutosInicio < fechamento &&
    minutosFim <= fechamento;

  return { json: { ...item.json, dentro_do_expediente: dentroDoExpediente } };
});

